head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf50300";
scwin.delay = false;
scwin.dmenus = undefined;
scwin.result = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf50300.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return " " + String(String((dma_pageContext.get("saleInstNm") ?? ""))); } },
        { childId: "__rb1", fn: function () { return String(String((dma_pageContext.get("saleIsuNm") ?? ""))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.dmenus = { "bmenu": 2, "mmenu": 1 };
        $('div#header').trigger('mouseleave');

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf50300.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_chgpass_onkeyup
 * @description ipt_chgpass 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_chgpass_onkeyup = function(e){
    try {
        scwin.fnDelayKeyup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf50300.ipt_chgpass_onkeyup' }); }
};

/**
 * @method
 * @name btn_passchk_onclick
 * @description btn_passchk 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_passchk_onclick = async function(e){
    try {
        await scwin.passchk()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf50300.btn_passchk_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnSavePassword
 * @description fn Save Password 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSavePassword = async function () {
    const sbmOptions = {
        id: "tx_fnSavePassword",
        method: "post",
        action: "/sales/sales.do",
        ref: "dma_fnSavePasswordReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_test
 * @description test 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_test = async function () {
    const sbmOptions = {
        id: "tx_test",
        method: "post",
        action: "/sales/sales.do",
        ref: "dma_testReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnNowPwCheck
 * @description fn Now Pw Check 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnNowPwCheck = async function () {
    const sbmOptions = {
        id: "tx_fnNowPwCheck",
        method: "post",
        action: "/sales/sales.do",
        ref: "dma_fnNowPwCheckReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnKISAPwCheck
 * @description fn KISAPw Check 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnKISAPwCheck = async function () {
    const sbmOptions = {
        id: "tx_fnKISAPwCheck",
        method: "post",
        action: "/common/common.do",
        ref: "dma_fnKISAPwCheckReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkPwd
 * @description check Pwd 처리
 * @param {*} aObj aObj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkPwd = async function (aObj) {
    const pwVal = aObj.getValue();
    if (pwVal.length < 8) {
        await $c.win.alert("변경 비밀번호를 9자 이상 입력하셔야 합니다.");
        (aObj && aObj.setFocus ? aObj.setFocus() : (aObj && aObj.focus ? aObj.focus() : void 0));
        return false;
    }
    const strChk = /^[\A-Za-z0-9_!@#$^&*()]{8,}$/;
    if (!(strChk.test(pwVal))) {
        await $c.win.alert("변경 비밀번호는 영문대문자,한글,띄어쓰기는 안됩니다.\n_!@#$^&*() 이외의 특수문자는 안됩니다.");
        (aObj && aObj.setFocus ? aObj.setFocus() : (aObj && aObj.focus ? aObj.focus() : void 0));
        return false;
    }
    const strIsurCd = $c.util.getComponent('ipt_isurCd').getValue();
    if (pwVal.indexOf(strIsurCd) !== -1) {
        await $c.win.alert("개인정보가 포함된 비밀번호는 사용하실 수 없습니다.");
        (aObj && aObj.setFocus ? aObj.setFocus() : (aObj && aObj.focus ? aObj.focus() : void 0));
        return false;
    }
    const alpha_t = "abcdefghijklmnopqrstuvwxyz";
    const sChar_t = "_!@#$^&*()";
    const number_t = "1234567890";
    let sChar_Count_t = 0;
    let alphaCheck_t = false;
    let numberCheck_t = false;
    for (let i = 0; i < pwVal.length; i++) {
        if (sChar_t.indexOf(pwVal.charAt(i)) !== -1) {
            sChar_Count_t++;
        }
        if (alpha_t.indexOf(pwVal.charAt(i)) !== -1) {
            alphaCheck_t = true;
        }
        if (number_t.indexOf(pwVal.charAt(i)) !== -1) {
            numberCheck_t = true;
        }
    }
    if (sChar_Count_t < 1 || alphaCheck_t !== true || numberCheck_t !== true) {
        await $c.win.alert("변경 비밀번호는 영문, 숫자, 특수문자의 조합이어야 합니다.");
        (aObj && aObj.setFocus ? aObj.setFocus() : (aObj && aObj.focus ? aObj.focus() : void 0));
        return false;
    }
    const charChk = /^[\a-z]{8,}$/;
    const numChk = /^[\d]{8,}$/;
    if (charChk.test(pwVal) || numChk.test(pwVal)) {
        await $c.win.alert('문자 또는 숫자만으로 구성된 변경 비밀번호는 사용하실 수 없습니다.');
        (aObj && aObj.setFocus ? aObj.setFocus() : (aObj && aObj.focus ? aObj.focus() : void 0));
        return false;
    }
    const keyboardWord = ["qwertyuiop", "poiuytrewq", "asdfghjkl", "lkjhgfdsa", "zxcvbnm", "mnbvcxz"];
    for (let i = 0; i < keyboardWord.length; i++) {
        for (let j = 0; j < keyboardWord[i].length; j++) {
            if (keyboardWord[i].substring(j, j + 4).length === 4) {
                if (!(pwVal.toLowerCase().indexOf(keyboardWord[i].substring(j, j + 4)) < 0)) {
                    await $c.win.alert('키보드상의 연속된 배열(' + keyboardWord[i].substring(j, j + 4) + ')로 구성된 변경 비밀번호는 사용하실 수 없습니다.');
                    (aObj && aObj.setFocus ? aObj.setFocus() : (aObj && aObj.focus ? aObj.focus() : void 0));
                    return false;
                }
            }
        }
    }
    return true;
};

/**
 * @method
 * @name passchk
 * @description passchk 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.passchk = async function () {
    const fm = (document.SendForm || { elements: [] });
    if ($c.str.getByteLength($c.util.getComponent('ipt_nowpass').getValue()) === 0) {
        await $c.win.alert("현재비밀번호를 입력하세요");
        $c.util.getComponent("ipt_nowpass").focus();
    } else {
        if ($c.str.getByteLength($c.util.getComponent('ipt_chgpass').getValue()) === 0) {
            await $c.win.alert("변경비밀번호를 입력하세요");
            $c.util.getComponent("ipt_chgpass").focus();
        } else {
            if ($c.str.getByteLength($c.util.getComponent('ipt_rechgpass').getValue()) === 0) {
                await $c.win.alert("변경비밀번호를 재 입력하세요");
                $c.util.getComponent("ipt_rechgpass").focus();
            } else {
                if (!await scwin.checkPwd($c.util.getComponent('ipt_chgpass'))) {
                    return;
                }
                if ($c.util.getComponent('ipt_chgpass').getValue()!== $c.util.getComponent('ipt_rechgpass').getValue()) {
                    await $c.win.alert("두개의 비밀번호가 일치하지 않습니다.");
                    $c.util.getComponent("ipt_chgpass").focus();
                    return;
                }
                if ($c.util.getComponent("ipt_perInfo1").checked === false) {
                    await $c.win.alert("개인정보 처리방침에 동의해주세요.");
                    /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                    return;
                }
                if ($c.util.getComponent("ipt_perInfo2").checked === false) {
                    await $c.win.alert("개인정보 수집 및 이용에 동의해주세요.");
                    /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                    return;
                }
                if ($c.util.getComponent('dma_fnSavePasswordReq').get('sendLevel') === "C") {
                    await $c.win.alert("보안등급이 낮습니다. 비밀번호를 다시 입력해주십시오.");
                    $c.util.getComponent("ipt_chgpass").focus();
                    return;
                }
                if (await $c.win.confirm("변경하시겠습니까?")) {
                    await scwin.fnNowPwCheck();
                    await scwin.fnSavePassword();
                }
            }
        }
    }
};

/**
 * @method
 * @name fnSavePassword
 * @description fn Save Password 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSavePassword = async function () {
    const fm = (document.SendForm || { elements: [] });
    if ($c.util.getComponent('ipt_temp').getValue() !== 'true') {
        await $c.win.alert("현재 비밀번호가 일치하지 않습니다.");
        return;
    } else {
        if ($c.util.getComponent('ipt_nowpass').getValue()=== $c.util.getComponent('ipt_chgpass').getValue()) {
            await $c.win.alert("현재 비밀번호는 사용하실 수 없습니다.");
            $c.util.getComponent("ipt_chgpass").focus();
            return;
        }
        $c.util.getComponent('dma_fnSavePasswordReq').set('method', "modifySalesPasswordInfo");
        fm.action = "/sales/sales.do";
        fm.target = "_self";
        await scwin.tx_fnSavePassword();
    }
};

/**
 * @method
 * @name test
 * @description test 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.test = async function () {
    const fm = (document.SendForm || { elements: [] });
    $c.util.getComponent('dma_fnSavePasswordReq').set('method', "modifySalesPasswordInfo");
    fm.action = "/sales/sales.do";
    fm.target = "_self";
    await scwin.tx_test();
};

/**
 * @method
 * @name fnDelayKeyup
 * @description fn Delay Keyup 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnDelayKeyup = function () {
    if (!scwin.delay) {
        scwin.delay = true;
        self.setTimeout(async function(){ await scwin.fnKISAPwCheck() }, 1000);
    }
};

/**
 * @method
 * @name fnReset
 * @description fn Reset 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnReset = function () {
    $c.util.getComponent('dma_fnSavePasswordReq').reset();
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name fnNowPwCheck_done
 * @description fn Now Pw Check done 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnNowPwCheck_done = function (data) {
    scwin.result = (typeof data === "string" ? JSON.parse(data) : data);
    $c.util.getComponent('ipt_temp').setValue(scwin.result.sendResult);
};

/**
 * @method
 * @name fnNowPwCheck
 * @description fn Now Pw Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnNowPwCheck = async function () {
    const r = await scwin.tx_fnNowPwCheck();
    try {
        scwin.fnNowPwCheck_done.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldbnf50300.fnNowPwCheck' });
    }
    return r;
};

/**
 * @method
 * @name fnKISAPwCheck_done
 * @description fn KISAPw Check done 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnKISAPwCheck_done = function (data) {
    scwin.result = (typeof data === "string" ? JSON.parse(data) : data);
    jsReturn(scwin.result.sendResult, scwin.result.sendLevel);
};

/**
 * @method
 * @name fnKISAPwCheck
 * @description fn KISAPw Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnKISAPwCheck = async function () {
    const r = await scwin.tx_fnKISAPwCheck();
    try {
        scwin.fnKISAPwCheck_done.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldbnf50300.fnKISAPwCheck' });
    }
    return r;
};
